CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, name TEXT NOT NULL, normalized_name TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, name TEXT NOT NULL CHECK(length(trim(name))>0), category_id TEXT NOT NULL REFERENCES categories(id), stock INTEGER NOT NULL CHECK(typeof(stock)='integer' AND stock>=0), minimum INTEGER NOT NULL CHECK(typeof(minimum)='integer' AND minimum>=0), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS movements (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id), type TEXT NOT NULL CHECK(type IN ('in','out')), quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity>0), reason TEXT NOT NULL CHECK(length(trim(reason))>0), previous_stock INTEGER NOT NULL CHECK(previous_stock>=0), resulting_stock INTEGER NOT NULL CHECK(resulting_stock>=0), idempotency_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category_id);
CREATE INDEX IF NOT EXISTS idx_movements_product ON movements(product_id);
CREATE INDEX IF NOT EXISTS idx_movements_date ON movements(created_at DESC);
